        boolean hasPlus = cleaned.startsWith("+");
        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
        String nationalSignificant = hasPlus
            ? digits
            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
